#[inductive(client_send)]
fn client_send_inductive(pre: Self,
    post: Self, j: nat, request: Request, cur_slot: bool)
{
    // Prove not_waiting_inv on post state
    assert(forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() ==> !post.slots.index(i)) by {
        assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() implies !post.slots.index(i) by {
            // If i == j, post.clients.index(j) is Waiting, not Idle, so this case is impossible
            // If i != j, the client and slot weren't changed by client_send
            if i == j {
                assert(post.clients.index(j).is_Waiting());
            } else {
                // For i != j, the state is unchanged
                // We need to use the pre invariant
                admit();
            }
        }
    };

    // Prove waiting_inv on post state  
    assert(forall |i: nat| #[trigger] post.client_waiting(i) ==> 
        post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)) by {
        assert forall |i: nat| #[trigger] post.client_waiting(i) implies
            post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
            // If i == j, we just deposited the request, so request_stored holds
            // If i != j, the waiting state didn't change for i
            admits()
        }
    };
}

