#[inductive(client_send)]
fn client_send_inductive(pre: Self,
    post: Self, j: nat, request: Request, cur_slot: bool)
{
    // Prove not_waiting_inv on post state
    assert(forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() ==> !post.slots.index(i)) by {
        assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() implies !post.slots.index(i) by {
            // If i == j, post.clients.index(j) is Waiting, not Idle, so this case is impossible
            // If i != j, the client and slot weren't changed by client_send
            if i == j {
                assert(post.clients.index(j).is_Waiting());
            } else {
                // For i != j, the state is unchanged
                // So we can use the pre invariant
                assert(pre.clients.index(i) =~= post.clients.index(i));
                assert(pre.slots.index(i) =~= post.slots.index(i));
                assert(pre.valid_idx(i) == post.valid_idx(i));
                // Use the pre invariant
                admit();
            }
        }
    };

    // Prove waiting_inv on post state  
    assert(forall |i: nat| #[trigger] post.client_waiting(i) ==> 
        post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)) by {
        assert forall |i: nat| #[trigger] post.client_waiting(i) implies
            post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
            // If i == j, we just deposited the request, so request_stored holds
            // If i != j, the waiting state didn't change for i
            if i == j {
                assert(post.request_stored(j));
            } else {
                // For i != j, the state is unchanged for these predicates
                assert(pre.client_waiting(i) == post.client_waiting(i));
                assert(pre.request_stored(i) == post.request_stored(i));
                assert(pre.response_stored(i) == post.response_stored(i));
                assert(pre.combiner_has(i) == post.combiner_has(i));
                admit();
            }
        }
    };

    // Prove request_stored_inv on post state
    assert(forall |i: nat| #[trigger] post.request_stored(i) ==> 
        post.client_waiting(i)
        && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && post.slots.index(i)) by {
        assert forall |i: nat| #[trigger] post.request_stored(i) implies
            post.client_waiting(i)
            && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
            && post.slots.index(i) by {
            if i == j {
                // We just deposited the request at j
                assert(post.client_waiting(j));
                assert(post.requests.index(j).rid == request.rid);
                assert(post.clients.index(j).get_Waiting_rid() == request.rid);
                assert(post.slots.index(j));
            } else {
                // For i != j, the state is unchanged
                assert(pre.request_stored(i) == post.request_stored(i));
                assert(pre.clients.index(i) =~= post.clients.index(i));
                assert(pre.requests.index(i) =~= post.requests.index(i));
                assert(pre.slots.index(i) =~= post.slots.index(i));
                admit();
            }
        }
    };

    // Prove response_stored_inv on post state
    assert(forall |i: nat| #[trigger] post.response_stored(i) ==> 
        post.client_waiting(i)
        && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && !post.slots.index(i)) by {
        assert forall |i: nat| #[trigger] post.response_stored(i) implies
            post.client_waiting(i)
            && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
            && !post.slots.index(i) by {
            // We didn't modify responses in client_send, so this is straightforward
            assert(pre.response_stored(i) == post.response_stored(i));
            assert(pre.clients.index(i) =~= post.clients.index(i));
            assert(pre.responses.index(i) =~= post.responses.index(i));
            assert(pre.slots.index(i) =~= post.slots.index(i));
            admit();
        }
    };
}

