            // Prove not_waiting_inv: for all i, if post.clients[i] is Idle then !post.slots[i]
            // For i == j: post.clients[j] is Waiting, so the implication holds vacuously
            // For i != j: clients and slots are unchanged, so the invariant holds by pre.not_waiting_inv
            // The verifier should be able to infer this
        }

